#!/usr/bin/env node

/**
 * GRANT ENUM MEMBERSHIP GUARD.
 *
 * `public.grant_permission` is the verb of `user_can`, and its members are string literals in every
 * RLS policy, so a wrong, missing or reordered member is an authorization defect that nothing else
 * reports. The declaration in `apps/supabase/supabase/schema/000-enums.sql` is the source of truth
 * for `grant_scope_type`, `grant_role_type` and `grant_permission`. This guard asserts:
 *
 *   - `packages/supabase-types/src/database.ts`, generated by `yarn db:types` from the applied
 *     database, carries the same members in the same order (enum ordinals are persisted). A
 *     declaration edited without a migration, or a migration never applied, shows up here;
 *   - only the two role levels `admin` and `editor` exist;
 *   - no suggestion verb exists, because no suggestions store is built.
 *
 * Differences are reported by name and in both directions, so a misspelling and a deletion cannot
 * cancel out in a count; an order difference is one finding. The member counts are printed before
 * any verdict, and an empty or truncated parse (below `PERMISSION_FLOOR`) withholds the verdict.
 * Every run also runs the self-test over `scripts/fixtures/grant-permission-enum/`: the seeded
 * fixture, compared against the clean one, must produce exactly `expected.violations`. When it does
 * not, the verdict is withheld.
 *
 * Usage:
 *   node scripts/assert-grant-permission-enum.mjs
 *   node scripts/assert-grant-permission-enum.mjs --self-test
 *
 * Exit codes:
 *   0 - the generated types agree with the schema declaration, in order, and the self-test passed
 *   1 - a finding, a population below the floor, an unreadable input, or a failed self-test
 */

import fs from 'node:fs';

const SELF = 'assert-grant-permission-enum';

const SCHEMA_FILE = 'apps/supabase/supabase/schema/000-enums.sql';
const GENERATED_FILE = 'packages/supabase-types/src/database.ts';

const FIXTURE_DIR = 'scripts/fixtures/grant-permission-enum';
const CLEAN_FIXTURE = `${FIXTURE_DIR}/enums.ok.sql`;
const VIOLATION_FIXTURE = `${FIXTURE_DIR}/enums.violations.sql`;
const EXPECTED_VIOLATIONS = `${FIXTURE_DIR}/expected.violations`;

const TYPE_NAMES = ['grant_scope_type', 'grant_role_type', 'grant_permission'];

/** The only role levels: every supported user type is an admin or an editor of some scope. */
const ROLE_LEVELS = ['admin', 'editor'];

/**
 * The floor for `grant_permission`. Below the real count on purpose: it catches a parser that has
 * stopped matching, not a deliberate change to the enum.
 */
const PERMISSION_FLOOR = 20;

/** Any member whose text carries this is a suggestion verb. */
const SUGGESTION_VERB_RE = /suggest/;

/** The remedy a schema/generated difference names. */
const REGENERATE_REMEDY =
  `Apply the migrations and regenerate the types with \`yarn db:types\`; a difference that survives that ` +
  `means ${SCHEMA_FILE} and the migrations disagree, so write the migration that matches the declaration.`;

function readOrNull(file) {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch (error) {
    console.error(`[ERROR] ${SELF}: could not read '${file}' (${error.message}).`);
    return null;
  }
}

/** Pulls the body between `CREATE TYPE public.<name> AS ENUM(` and its closing parenthesis, then collects the single-quoted literals in order. */
function parseSqlEnum(sql, typeName) {
  const match = sql.match(new RegExp(`CREATE TYPE public\\.${typeName} AS ENUM\\(([\\s\\S]*?)\\);`));
  if (!match) return [];
  return [...match[1].matchAll(/'([^']+)'/g)].map((m) => m[1]);
}

/** Every grant type parsed from one SQL source. */
function parseSqlEnums(sql) {
  return Object.fromEntries(TYPE_NAMES.map((typeName) => [typeName, parseSqlEnum(sql, typeName)]));
}

/**
 * Pulls the union that follows the type name inside the generated `Enums` block of the `public`
 * schema. The search is confined to that block: `graphql_public` has an earlier, empty `Enums`
 * block, and a later `Constants` block spells every enum again as a runtime array.
 */
function parseGeneratedEnum(ts, typeName) {
  const schemaStart = ts.indexOf('\n  public: {');
  if (schemaStart === -1) return [];
  const start = ts.indexOf('\n    Enums: {', schemaStart);
  if (start === -1) return [];
  const end = ts.indexOf('\n    CompositeTypes', start);
  const block = end === -1 ? ts.slice(start) : ts.slice(start, end);
  const match = block.match(new RegExp(`\\n      ${typeName}:([\\s\\S]*?);`));
  if (!match) return [];
  return [...match[1].matchAll(/'([^']+)'/g)].map((m) => m[1]);
}

/** Reports the two directions separately, and order as one fact rather than one fact per member. */
function compareMembers(typeName, reference, referenceLabel, members, channelLabel, remedy) {
  const suffix = remedy ? ` ${remedy}` : '';
  const findings = [];
  for (const member of reference) {
    if (!members.includes(member)) {
      findings.push(
        `${typeName}: '${member}' is declared in ${referenceLabel} but absent from ${channelLabel}.${suffix}`
      );
    }
  }
  for (const member of members) {
    if (!reference.includes(member)) {
      findings.push(`${typeName}: '${member}' is in ${channelLabel} but not declared in ${referenceLabel}.${suffix}`);
    }
  }
  if (findings.length === 0 && JSON.stringify(members) !== JSON.stringify(reference)) {
    findings.push(
      `${typeName}: ${channelLabel} has the members of ${referenceLabel} in a different order, and enum ordinals ` +
        `are persisted.${suffix}`
    );
  }
  return findings;
}

/** The two rules the comparison cannot express, since it only checks that two channels agree. */
function checkProhibitions(channelLabel, roleMembers, permissionMembers) {
  const findings = [];
  for (const member of roleMembers) {
    if (!ROLE_LEVELS.includes(member)) {
      findings.push(
        `grant_role_type: ${channelLabel} carries a third role level '${member}'. Only two role levels exist, ` +
          'admin and editor: managing editors is the permission project.manage_editors, so a third level ' +
          'would be a security enum member nothing grants.'
      );
    }
  }
  for (const member of permissionMembers) {
    if (SUGGESTION_VERB_RE.test(member)) {
      findings.push(
        `grant_permission: ${channelLabel} carries a suggestion verb '${member}'. No suggestion verb exists, ` +
          'because no suggestions store is built.'
      );
    }
  }
  return findings;
}

function sortedEqual(a, b) {
  if (a.length !== b.length) return false;
  const x = [...a].sort();
  const y = [...b].sort();
  return x.every((value, index) => value === y[index]);
}

/**
 * The comparator over two committed fixtures: `enums.ok.sql`, a miniature enums file, and
 * `enums.violations.sql`, the same with four seeded defects (a misspelled member, a deleted member,
 * a suggestion verb and a third role level). The clean fixture is the reference for both legs, so
 * the self-test does not depend on the live schema. The clean leg must parse a full population and
 * report nothing; the seeded leg must report exactly the committed findings.
 */
function selfTest() {
  const cleanSrc = readOrNull(CLEAN_FIXTURE);
  const violationSrc = readOrNull(VIOLATION_FIXTURE);
  const expectedRaw = readOrNull(EXPECTED_VIOLATIONS);
  if (cleanSrc === null || violationSrc === null || expectedRaw === null) {
    return { passed: false, summary: 'self-test could not read its fixtures, so it proved nothing' };
  }

  const expected = expectedRaw.split('\n').filter((line) => line.trim() !== '');
  const reference = parseSqlEnums(cleanSrc);
  const audit = (sql) => {
    const parsed = parseSqlEnums(sql);
    const findings = [];
    for (const typeName of TYPE_NAMES) {
      findings.push(
        ...compareMembers(
          typeName,
          reference[typeName],
          'the clean fixture',
          parsed[typeName],
          'the fixture under test'
        )
      );
    }
    findings.push(...checkProhibitions('the fixture under test', parsed.grant_role_type, parsed.grant_permission));
    return findings;
  };
  const cleanFindings = audit(cleanSrc);
  const violationFindings = audit(violationSrc);

  const summary =
    `self-test: ${CLEAN_FIXTURE} -> ${cleanFindings.length} finding(s), ` +
    `${VIOLATION_FIXTURE} -> ${violationFindings.length} finding(s) against ${expected.length} expected`;

  let passed = true;
  if (reference.grant_permission.length < PERMISSION_FLOOR) {
    passed = false;
    console.error(
      `[ERROR] ${SELF}: the clean fixture parsed to ${reference.grant_permission.length} grant_permission ` +
        `member(s), below the floor of ${PERMISSION_FLOOR}, so the parser has stopped matching.`
    );
  }
  if (cleanFindings.length !== 0) {
    passed = false;
    console.error(
      `[ERROR] ${SELF}: the clean fixture produced ${cleanFindings.length} finding(s) and must produce none:`
    );
    for (const finding of cleanFindings) console.error(`          ${finding}`);
  }
  if (expected.length === 0) {
    passed = false;
    console.error(
      `[ERROR] ${SELF}: '${EXPECTED_VIOLATIONS}' is empty, so the seeded fixture would be compared against nothing.`
    );
  }
  if (!sortedEqual(violationFindings, expected)) {
    passed = false;
    console.error(`[ERROR] ${SELF}: the seeded fixture did not produce the committed expected findings.`);
    for (const finding of violationFindings) {
      if (!expected.includes(finding)) console.error(`          produced but not expected: ${finding}`);
    }
    for (const finding of expected) {
      if (!violationFindings.includes(finding)) console.error(`          expected but not produced: ${finding}`);
    }
  }

  return { passed, summary };
}

function main() {
  if (process.argv.includes('--self-test')) {
    const { passed, summary } = selfTest();
    console.log(`Grant enum membership guard — ${summary}.`);
    process.exitCode = passed ? 0 : 1;
    return;
  }

  const schemaSrc = readOrNull(SCHEMA_FILE);
  const generatedSrc = readOrNull(GENERATED_FILE);
  if (schemaSrc === null || generatedSrc === null) {
    console.error(
      `[ERROR] ${SELF}: a channel could not be read, so no comparison was made and the verdict is withheld.`
    );
    process.exitCode = 1;
    return;
  }

  const schema = parseSqlEnums(schemaSrc);
  const generated = Object.fromEntries(
    TYPE_NAMES.map((typeName) => [typeName, parseGeneratedEnum(generatedSrc, typeName)])
  );

  // --- The census, printed before any verdict --------------------------------
  console.log(`Grant enum membership guard — census (schema / generated):`);
  for (const typeName of TYPE_NAMES) {
    console.log(`  ${typeName}: ${schema[typeName].length} / ${generated[typeName].length}`);
  }

  // --- The non-vacuity floor -------------------------------------------------
  const floorFailures = [];
  for (const [label, parsed] of [
    [SCHEMA_FILE, schema],
    [GENERATED_FILE, generated]
  ]) {
    for (const typeName of TYPE_NAMES) {
      if (parsed[typeName].length === 0) {
        floorFailures.push(`${typeName}: the parser found no members in ${label}, so nothing was compared`);
      }
    }
    if (parsed.grant_permission.length > 0 && parsed.grant_permission.length < PERMISSION_FLOOR) {
      floorFailures.push(
        `grant_permission: ${label} yielded ${parsed.grant_permission.length} member(s), below the floor of ` +
          `${PERMISSION_FLOOR}, which is a parser that has stopped matching rather than a shrunken enum`
      );
    }
  }
  if (floorFailures.length > 0) {
    for (const failure of floorFailures) console.error(`[ERROR] ${SELF}: ${failure}.`);
    console.error(
      `[ERROR] ${SELF}: a population below the floor means this guard proved nothing; the verdict is withheld.`
    );
    process.exitCode = 1;
    return;
  }

  // --- The comparison and the prohibitions -----------------------------------
  const findings = [];
  for (const typeName of TYPE_NAMES) {
    findings.push(
      ...compareMembers(typeName, schema[typeName], SCHEMA_FILE, generated[typeName], GENERATED_FILE, REGENERATE_REMEDY)
    );
  }
  findings.push(...checkProhibitions(SCHEMA_FILE, schema.grant_role_type, schema.grant_permission));

  for (const finding of findings) console.error(`[ERROR] ${SELF}: ${finding}`);

  // --- The self-test, in this same invocation ---------------------------------
  const { passed: selfTestPassed, summary: selfTestSummary } = selfTest();
  if (!selfTestPassed) {
    console.error(
      `[ERROR] ${SELF}: the self-test did not match its committed expectations (printed above). The result over ` +
        'the real channels says nothing until this passes, so the verdict is withheld.'
    );
  }

  console.log(`Grant enum membership guard — ${findings.length} finding(s); ${selfTestSummary}.`);
  process.exitCode = findings.length > 0 || !selfTestPassed ? 1 : 0;
}

main();
